523	/// Resize the terminal.
524	pub fn resize(
525	    self: *Termio,
526	    td: *ThreadData,
527	    size: renderer.Size,
528	) !void {
529	    self.size = size;
530	    const grid_size = size.grid();
531	
532	    // Enter the critical area that we want to keep small
533	    {
534	        self.renderer_state.mutex.lockUncancelable(global.io());
535	        defer self.renderer_state.mutex.unlock(global.io());
536	
537	        // Resizing the pty can immediately wake the shell with SIGWINCH.
538	        // Hold the same lock used by processOutput before notifying it, so
539	        // its redraw cannot be parsed against the old terminal dimensions.
540	        try self.backend.resize(grid_size, size.terminal());
541	
542	        // Update the size of our terminal state
543	        try self.terminal.resize(
544	            self.alloc,
545	            .{
546	                .cols = grid_size.columns,
547	                .rows = grid_size.rows,
548	                .cell_size_px = .{
549	                    .width = self.size.cell.width,
550	                    .height = self.size.cell.height,
551	                },
552	            },
553	        );
554	
555	        // If we have size reporting enabled we need to send a report.
556	        if (self.terminal.modes.get(.in_band_size_reports)) {
557	            try self.sizeReportLocked(td, .mode_2048);
558	        }
559	    }
560	
561	    // Mail the renderer so that it can update the GPU and re-render
562	    _ = self.renderer_mailbox.push(global.io(), .{ .resize = size }, .{ .forever = {} });
563	    self.renderer_wakeup.notify() catch {};
564	}
565	
566	/// Make a size report.
567	pub fn sizeReport(self: *Termio, td: *ThreadData, style: termio.Message.SizeReport) !void {
568	    self.renderer_state.mutex.lockUncancelable(global.io());
569	    defer self.renderer_state.mutex.unlock(global.io());
570	    try self.sizeReportLocked(td, style);
571	}
572	
573	fn sizeReportLocked(self: *Termio, td: *ThreadData, style: termio.Message.SizeReport) !void {
574	    const grid_size = self.size.grid();
575	    const report_size: terminalpkg.size_report.Size = .{
576	        .rows = grid_size.rows,
577	        .columns = grid_size.columns,
578	        .cell_width = self.size.cell.width,
579	        .cell_height = self.size.cell.height,
580	    };
581	
582	    // 1024 bytes should be enough for size report since report
583	    // in columns and pixels.
584	    var buf: [1024]u8 = undefined;
585	    var writer: std.Io.Writer = .fixed(&buf);
586	    try terminalpkg.size_report.encode(
587	        &writer,
588	        style,
589	        report_size,
590	    );
591	
592	    try self.queueWrite(td, writer.buffered(), false);
593	}
